import os

from sqlalchemy import URL, create_engine
from sqlalchemy.orm import declarative_base, sessionmaker

# Generated by OpenAI Codex on 2026-11-01. URL.create safely escapes passwords.
# COMMENTS ADDED BY CARTER
DATABASE_URL = os.environ.get("DATABASE_URL") or URL.create(
    "postgresql+psycopg2",
    username="cats",
    password=os.environ["DB_PASSWORD"],
    host=os.environ.get(
        "DB_HOST", "127.0.0.1"
    ),  # DEFAULTS TO IPV4 LOOPBACK IF ENV VAR NOT SET
    port=int(os.environ.get("DB_PORT", "5432")),  # DEFAULTS TO 5432 IF ENV VAR NOT SET
    database="cats",
)

engine = create_engine(
    DATABASE_URL, pool_pre_ping=True, future=True
)  # Add `echo=True` for verbose logging

SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine, future=True)
Base = declarative_base()


def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()
